import os, sys; sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from common import Bank
B = Bank('127.', 1215, own='cte_138.jsonl')
def H(code, d, q, right, wrong, e): return B.hand(code, d, q, right, wrong, e)
H("888.d.9.A",3,"A student inspects the cowling, wheel fairings and control cables on a trainer, following the Part 43 100-hour checklist. She is:","performing a portion of a 100-hour inspection in accordance with 14 CFR Part 43",["skipping an inspection","painting the airplane","fueling the airplane"],"100-hour inspection.")
H("888.d.9.A",4,"A 100-hour inspection is required for aircraft that are:","used to carry persons for hire or for flight instruction for hire",["stored in a hangar","owned by retirees","never flown"],"Who needs 100-hour.")
H("888.d.9.B",3,"After the inspection, the mechanic writes that the aircraft is returned to service, or lists the defects that make it unairworthy. She is:","entering the results of a 100-hour inspection, including airworthy and unairworthy conditions",["leaving no record","hiding defects","guessing at results"],"Log the result.")
H("888.d.9.B",4,"If an inspection finds a defect that makes an aircraft unairworthy, the mechanic must:","give the owner a signed, dated list of the discrepancies",["say nothing","paint over it","sign it as airworthy"],"Discrepancy list.")
H("888.d.9.C",3,"A mechanic checks the aircraft's records and equipment against AD and registration paperwork to confirm they comply. She is:","analyzing and inspecting equipment and documents to determine compliance",["ignoring documents","only washing the plane","avoiding records"],"Compliance check.")
H("888.d.9.C",4,"A required AD that has not been recorded as complied with means the aircraft:","may not be airworthy until it is resolved",["is fine","is faster","is lighter"],"AD status.")
H("888.d.10.A",3,"Before lifting a plane, Ravi checks the jack's rating, uses a level floor and keeps people out from under the plane. He is identifying:","safety precautions when using aircraft jacks",["no precautions","shortcuts","unsafe habits"],"Jack safety.")
H("888.d.10.A",4,"Jacking an aircraft outdoors in strong wind is unsafe because it can:","tip or shift the aircraft off the jacks",["help balance","speed lifting","clean the jacks"],"Wind and jacks.")
H("888.d.10.B",3,"A mechanic wears eye protection and relieves system pressure before loosening a hydraulic line. She is identifying:","safety precautions when working with high-pressure fluids and gases",["no precautions","shortcuts","random steps"],"Pressure safety.")
H("888.d.10.B",4,"A pinhole leak in a high-pressure hydraulic line can inject fluid through the skin, so a mechanic should:","never check for leaks with bare hands",["use bare fingers","hold a hand close","ignore it"],"Injection hazard.")
H("888.d.10.C",3,"A shop keeps hydraulic fluid in closed, labeled containers away from heat and ignition. This shows:","safety precautions in the storage and handling of hydraulic fluid",["unsafe storage","no labels","open containers"],"Fluid storage.")
H("888.d.10.C",4,"Hydraulic fluid containers should be labeled and kept sealed to prevent:","contamination and mix-ups between fluid types",["fluid improvements","extra cleaning","faster flow"],"Labeling.")
H("888.d.10.D",3,"A mechanic puts gear safety pins in and keeps clear of the wheel wells during a retraction test. She is identifying:","safety precautions for operating retractable landing gear",["no precautions","skipping pins","working under gear"],"Retraction safety.")
H("888.d.10.D",4,"Ground lock pins are installed to prevent:","the gear from retracting while personnel are working",["the gear extending","tires wearing","fuel flowing"],"Gear pins.")
H("888.d.10.E",3,"Before removing a wheel, a mechanic chocks the other wheels, deflates the tire and uses a wheel dolly. She is identifying:","safety precautions in landing gear, tire and wheel maintenance",["no precautions","unsafe steps","skipping chocks"],"Wheel safety.")
H("888.d.10.E",4,"A tire should be deflated before wheel disassembly because trapped pressure can:","cause a violent explosion",["clean the rim","cool the brake","soften the tire"],"Tire explosion.")
H("888.d.10.F",3,"A student lists struts, trunnions, drag links and retraction actuators as parts of a retractable gear. She is describing:","fixed and retractable landing gear systems and components",["propeller systems","fuel systems","oxygen systems"],"Gear systems.")
H("888.d.10.F",4,"The main difference between fixed and retractable gear is that retractable gear:","folds into the airframe after takeoff",["never moves","has no tires","is always bigger"],"Retractable gear.")
H("888.d.10.G",3,"A mechanic checks the oleo strut for correct air pressure and fluid level and lubricates the pivot points. She is explaining:","the necessity of landing gear strut servicing and lubrication",["no need for service","a random task","an optional chore"],"Strut servicing.")
H("888.d.10.G",4,"An oleo strut that has lost its air or fluid will:","bottom out and give a harsh ride and landing",["ride perfectly","hold more weight","reduce tire wear"],"Underserviced strut.")
H("888.d.10.H",3,"A mechanic compares checking bungee cords for stretch and cracks with checking a spring steel leg for cracks and bends. She is:","describing and comparing inspection methods for bungee and spring steel gear",["avoiding inspection","painting gear","fueling the aircraft"],"Gear inspection types.")
H("888.d.10.H",4,"Spring steel landing gear is common on:","light general aviation airplanes",["large airliners","helicopters only","rockets"],"Spring steel gear.")
H("888.d.10.I",3,"A student compares castering nose wheels steered with differential braking and nose wheels steered through rudder pedals linked by rods or cables. She is:","describing and comparing aircraft steering systems",["avoiding steering","ignoring wheels","guessing"],"Steering systems.")
H("888.d.10.I",4,"A castering nose wheel is steered mainly by:","differential braking and rudder",["no input","a steering wheel only","an electric motor only"],"Castering.")
H("888.d.10.J",3,"A mechanic tests the gear-down lights, the position switches and the gear warning horn. She is explaining:","landing gear position and warning system inspection, check and servicing",["a paint check","a prop check","a tire check"],"Gear warning.")
H("888.d.10.J",4,"A gear warning horn sounds when the gear is not down and locked and the:","throttle is reduced for landing",["radio is on","cabin is hot","door is open"],"Gear horn logic.")
H("888.d.10.K",3,"A mechanic checks brake pads for wear, disc thickness and signs of overheating. She is explaining:","brake assembly servicing and inspection",["gear retraction","wheel painting","tire inflation"],"Brake inspection.")
H("888.d.10.K",4,"A brake disc worn below the manufacturer's minimum thickness should be:","replaced",["reused","painted","ignored"],"Replace worn disc.")
H("888.d.10.L",3,"A student compares independent master cylinders on rudder pedals with a power boost system that uses system hydraulic pressure. She is:","describing and comparing brake actuating systems",["describing engines","describing fuel","describing oxygen"],"Brake actuation.")
H("888.d.10.L",4,"On many light airplanes, toe brakes are operated by:","pushing the top of the rudder pedals",["pulling a handle only","a foot pedal on the floor only","a voice command"],"Toe brakes.")
H("888.d.11.A",3,"A student runs a retractable gear through a swing test and checks the fluid level in the actuator. She is:","inspecting and servicing landing gear such as fixed or retractable systems",["painting the gear","washing the plane","ignoring the gear"],"Gear service.")
H("888.d.11.A",4,"A gear swing test is done with the aircraft on jacks so the gear can:","retract and extend without bearing weight",["stay stuck","break the jacks","avoid inspection"],"Swing test.")
H("888.d.11.B",3,"A mechanic places jacks at the specified jack points and raises the aircraft level before cycling the gear. She is:","jacking an aircraft for a gear retraction check",["lifting by the prop","skipping jack points","guessing the points"],"Jacking.")
H("888.d.11.B",4,"Jack points are specified in the manual because lifting elsewhere can:","damage the structure",["improve balance","strengthen the skin","speed lifting"],"Use jack points.")
H("888.d.11.C",3,"A technician checks wheel bearings for roughness, brake discs for wear and tire tread for cuts. She is:","inspecting wheels, brakes, bearings and tires",["skipping checks","painting the wheel","washing the plane"],"Wheel inspection.")
H("888.d.11.C",4,"A wheel bearing that feels rough when spun should be:","cleaned, inspected and replaced if damaged",["ignored","painted","reused"],"Bearing check.")
H("888.d.11.D",3,"A mechanic pumps the pedal and opens the bleeder screw until no bubbles come out of the brake line. She is:","bleeding air from a hydraulic brake system",["adding air","draining fuel","painting lines"],"Brake bleeding.")
H("888.d.11.D",4,"Air in a hydraulic brake line makes the pedal feel:","spongy",["firm","hot","heavy"],"Spongy pedal.")
H("888.d.11.E",3,"A student runs a gloved hand and a flashlight around a tire, looking for cuts, bulges and flat spots. She is:","inspecting a tire for defects",["painting the tire","adding tread","buying a tire"],"Tire inspection.")
H("888.d.11.E",4,"A bulge in a tire sidewall means the tire should be:","removed from service",["ignored","painted","over-inflated"],"Bulge means replace.")
H("888.d.11.F",3,"A mechanic bleeds off the strut's pressure, removes the old valve and installs a new one. She is:","replacing a shock strut air valve",["replacing a tire","replacing a seat","replacing a window"],"Air valve.")
H("888.d.11.F",4,"Before removing a strut air valve, a mechanic must first:","relieve the air pressure in the strut",["add more pressure","skip the step","heat the valve"],"Relieve pressure.")
H("888.d.11.G",3,"A mechanic uses a manual to find the toe-in and camber specifications for the main gear. She is:","locating and explaining the process for checking landing gear alignment",["guessing alignment","ignoring wheels","painting the gear"],"Gear alignment.")
H("888.d.11.G",4,"Misaligned landing gear can cause:","uneven tire wear and poor handling",["even wear","better handling","less drag"],"Alignment effects.")
H("888.d.11.H",3,"A pilot reports a nose wheel that vibrates at taxi speed. The mechanic checks the shimmy damper, the wheel balance and loose nose gear parts. She is:","troubleshooting a steering problem such as nose-wheel shimmy",["ignoring the report","painting the nose wheel","adding weight"],"Shimmy.")
H("888.d.11.H",4,"A worn shimmy damper or loose torque links can cause:","nose wheel shimmy",["a smoother ride","better steering","no vibration"],"Shimmy causes.")
H("888.d.11.I",3,"A student identifies the gear position switches, indicator lights and warning horn on a diagram. She is:","identifying landing gear position and warning system components",["identifying engines","identifying seats","identifying tires"],"Gear indication parts.")
H("888.d.11.I",4,"A gear position switch tells the indicator system:","whether the gear is up, down or in transit",["the fuel level","the tire size","the pilot's name"],"Gear switch.")
H("888.d.11.J",3,"The gear-down light stays dark even though the gear is down. The mechanic tests the bulb, the wiring and the switch. She is:","troubleshooting a landing gear position and warning system",["replacing the tires","painting the light","ignoring the report"],"Gear light fault.")
H("888.d.11.J",4,"A good first step in troubleshooting a gear indicator that fails is to:","check the bulb and the circuit breaker",["replace the gear","repaint the cover","ignore the circuit"],"Start simple.")
H("888.d.11.K",3,"A mechanic measures the brake lining against the wear limit and checks for leaks around the caliper. She is:","inspecting a brake for serviceability",["washing a tire","painting a drum","adding air"],"Brake serviceability.")
H("888.d.11.K",4,"Glazed, oil-soaked brake linings should be:","replaced and the leak source fixed",["left in place","polished","painted"],"Contaminated linings.")
H("888.d.11.L",3,"A student looks for bent tubes, cracks near welds and corrosion on the legs of a tube-type gear. She is:","inspecting tube landing gear for damage",["washing the gear","ignoring the gear","painting only"],"Tube gear check.")
H("888.d.11.L",4,"A crack near a weld on a landing gear leg should lead to:","removal from service and evaluation or repair per the manual",["a coat of paint","ignoring it","a bigger tire"],"Cracked gear.")
H("888.d.12.A",3,"A student labels a diagram with a reservoir, filter, flexible hose, rigid line, pump and accumulator. She is:","describing hydraulic system components",["describing pneumatic only","describing fuel only","describing oxygen only"],"Hydraulic parts.")
H("888.d.12.A",4,"The component that stores fluid for a hydraulic system is the:","reservoir",["accumulator","actuator","filter"],"Reservoir.")
H("888.d.12.B",3,"A mechanic explains that the filter traps particles, the pump creates flow and the accumulator smooths pressure surges. She is:","explaining the function of hydraulic system components",["avoiding explanation","naming tires","naming engines"],"Component functions.")
H("888.d.12.B",4,"An accumulator in a hydraulic system helps by:","storing pressure and smoothing surges",["cooling fuel","filtering air","driving the prop"],"Accumulator.")
H("888.d.12.C",3,"A technician follows a checklist to inspect, operate, service and troubleshoot the landing gear hydraulic system. She is:","explaining hydraulic system operation, inspections, operational checks, servicing and troubleshooting",["ignoring the system","painting the system","guessing"],"Hydraulic ops.")
H("888.d.12.C",4,"A hydraulic system that loses fluid without an external leak may have:","an internal leak, such as a worn seal",["too much air","a clean filter","a cold cabin"],"Internal leak.")
H("888.d.12.D",3,"A student names the air compressor, air bottle, regulator, moisture trap and air lines in a pneumatic system. She is:","describing pneumatic system components",["describing hydraulic only","describing engines","describing seats"],"Pneumatic parts.")
H("888.d.12.D",4,"A moisture separator in a pneumatic system is used to:","remove water from the compressed air",["add water","add oil","add heat"],"Moisture trap.")
H("888.d.12.E",3,"A mechanic explains that a regulator keeps air pressure at a steady level for the actuators. She is:","explaining the function of pneumatic system components",["avoiding the topic","naming tires","describing fuel"],"Pneumatic functions.")
H("888.d.12.E",4,"A check valve in an air line allows flow:","in one direction only",["both ways","no way","only when hot"],"Check valve.")
H("888.d.12.F",3,"A technician checks air bottle pressure, drains moisture and tests the emergency gear blow-down. She is:","explaining pneumatic system operation, inspections, operational checks and servicing",["painting the bottle","skipping checks","washing the plane"],"Pneumatic ops.")
H("888.d.12.F",4,"Pneumatic systems use air or nitrogen, so a leak will typically show as a:","hissing sound or pressure drop",["fluid puddle","bright color","fuel smell"],"Air leak signs.")
H("888.d.12.G",3,"A mechanic sorts seals made of rubber, neoprene and Teflon and checks which fluid each can handle. She is:","identifying types of hydraulic seals and fluid compatibility",["avoiding seals","painting seals","ignoring fluids"],"Seal compatibility.")
H("888.d.12.G",4,"A seal made for mineral oil fluid can fail quickly if used with:","phosphate-ester (Skydrol) fluid",["no fluid","fresh water","clean air"],"Wrong seal swells.")
H("888.d.12.H",3,"A student reads that a burst high-pressure line can throw fluid or gas with great force. She is researching:","the risks associated with high-pressure gases and fluids",["no risks","paint choices","tire brands"],"High-pressure risk.")
H("888.d.12.H",4,"Compressed gas bottles are dangerous because a damaged valve can:","turn the bottle into a projectile",["fill the shop with light","cool the shop","clean the shop"],"Bottle hazard.")
H("888.d.12.I",3,"A student researches what could happen if a technician opens a fitting before relieving the system pressure. She is identifying:","the risks of not relieving system pressure before maintenance",["no risks","paint risks","tire risks"],"Relieve pressure first.")
H("888.d.12.I",4,"Opening a line that still holds pressure may result in:","fluid spray and injury",["a cleaner line","a cooler system","a faster repair"],"Spray hazard.")
H("888.d.12.J",3,"A student researches the risks of leaving fluid in open cans or near ignition sources. She is identifying:","the risks associated with storage and handling of hydraulic fluids",["no risks","paint choices","tire brands"],"Fluid handling.")
H("888.d.12.J",4,"Some hydraulic fluids can irritate skin and eyes, so handlers should wear:","gloves and eye protection",["nothing","sandals","a hat only"],"PPE for fluid.")
H("888.d.12.K",3,"A mechanic is reminded that mixing two different fluid types in one system can ruin the seals. She is researching:","the risks of cross-contamination of hydraulic fluids",["no risks","engine noise","tire wear"],"Cross-contamination.")
H("888.d.12.K",4,"Adding the wrong type of fluid to a hydraulic reservoir can cause:","seal damage and system failure",["better pressure","a cleaner system","longer life"],"Wrong fluid.")
H("888.d.13.A",3,"A mechanic compares mineral-based, synthetic and phosphate-ester hydraulic fluids on a chart. She is:","identifying different types of hydraulic fluids",["avoiding fluids","painting fluids","mixing fluids"],"Fluid types.")
H("888.d.13.A",4,"Mineral-based hydraulic fluids are usually dyed:","red",["black","clear","white"],"Mineral fluid color.")
H("888.d.13.B",3,"A mechanic lubricates the seal, slides it into the groove and installs the backup ring on the pressure-free side. She is:","installing seals and backup rings in a hydraulic component",["removing a tire","painting a part","cutting a hose"],"Install seals.")
H("888.d.13.B",4,"A new seal should be lubricated with:","clean hydraulic fluid of the system type",["dry grit","any oil","paint thinner"],"Lube the seal.")
H("888.d.13.C",3,"A student removes a hydraulic filter element, cleans the bowl and replaces the element with a new gasket. She is:","removing, cleaning, inspecting and installing a hydraulic filter",["ignoring the filter","painting the filter","adding fluid"],"Filter service.")
H("888.d.13.C",4,"When a filter element is replaced, the old one should be:","inspected for metal particles",["thrown away unseen","reused","painted"],"Inspect old filter.")
H("888.d.13.D",3,"A mechanic checks the level on the sight glass, adds the correct fluid and tightens the cap. She is:","servicing a hydraulic system reservoir",["draining fuel","adding air","cleaning tires"],"Reservoir service.")
H("888.d.13.D",4,"A reservoir should be filled to the proper level because overfilling can:","cause fluid to overflow when it expands",["cool the system","improve flow","lower pressure"],"Overfill.")
H("888.d.13.E",3,"A mechanic operates the system and bleeds each line until the fluid shows no air bubbles. She is:","purging air from a hydraulic system",["adding air","removing fuel","painting lines"],"Purge air.")
H("888.d.13.E",4,"Air trapped in a hydraulic system can cause:","spongy or erratic operation",["perfect operation","faster pumping","cooler fluid"],"Air effects.")
H("888.d.13.F",3,"A technician checks fittings, hoses and actuators for wetness and checks air lines for hissing. She is:","inspecting hydraulic and pneumatic systems for leaks",["avoiding the systems","painting hoses","adding fluid"],"Leak inspection.")
H("888.d.13.F",4,"A hydraulic leak is often found by looking for:","wet spots, stains and fluid residue",["clean areas","dry paint","bright lights"],"Leak signs.")
H("888.d.13.G",3,"After finding a seep, the mechanic cleans the area, runs the system and traces the wet spot to its source. She is:","troubleshooting hydraulic and pneumatic systems for leaks",["ignoring the seep","painting the leak","adding more fluid"],"Trace leaks.")
H("888.d.13.G",4,"Cleaning a suspected leak area before testing helps the mechanic to:","see where fresh fluid is coming from",["hide the leak","add pressure","remove the system"],"Clean then test.")
H("888.d.13.H",3,"A mechanic opens the maintenance manual and finds the fluid type, fill level and servicing steps for the gear system. She is:","locating and explaining hydraulic fluid servicing instructions",["guessing fluid","ignoring steps","using memory"],"Fluid servicing data.")
H("888.d.13.H",4,"Hydraulic servicing instructions should be taken from:","the aircraft maintenance manual",["a rumor","a flyer","a radio ad"],"Use the AMM.")
H("888.d.13.I",3,"A technician matches a particular aircraft to the fluid listed on its reservoir placard and in the manual. She is:","identifying and selecting hydraulic fluid for a given aircraft",["guessing fluid","using any fluid","using water"],"Select fluid.")
H("888.d.13.I",4,"The type of hydraulic fluid for an aircraft is often listed:","on a placard near the reservoir",["on the tail","on the seat","in the engine"],"Fluid placard.")
H("888.d.13.J",3,"A mechanic finds the section in the manual that shows how to install a seal, backup ring or gasket in the right order. She is:","locating installation procedures for a seal, backup ring or gasket",["avoiding procedures","guessing","using slang"],"Seal procedures.")
H("888.d.13.J",4,"Following the exact installation procedure for a backup ring helps prevent:","extrusion of the seal under pressure",["better sealing","longer life","cleaner fluid"],"Backup ring.")
H("888.d.14.A",3,"A student explains how bleed air from the engine heats a cabin and pressurizes it. She is:","explaining the operation and purpose of pressurization systems and bleed air heating",["avoiding heating","explaining fuel","explaining tires"],"Bleed air.")
